import{_ as a,o as p,c as s,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"DCloud AppKey 是什么？离线打包三要素必须一致","description":"DCloud AppKey 是后台生成的离线授权凭证；Android 运行时校验 appid、包名、签名 SHA1、AppKey 四者一致。Gradle Release 构建可提前拦截空 AppKey。","frontmatter":{"title":"DCloud AppKey 是什么？离线打包三要素必须一致","date":"2026-05-19T00:00:00.000Z","tags":["uni-app","DCloud","离线打包","Android","iOS","AppKey","Gradle"],"categories":["移动开发"],"description":"DCloud AppKey 是后台生成的离线授权凭证；Android 运行时校验 appid、包名、签名 SHA1、AppKey 四者一致。Gradle Release 构建可提前拦截空 AppKey。"},"headers":[],"relativePath":"posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致.md","filePath":"posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致.md","lastUpdated":1790163617000}'),d={name:"posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致.md"};function n(o,e,l,r,i,c){return p(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="dcloud-appkey-是什么" tabindex="-1">DCloud AppKey 是什么？ <a class="header-anchor" href="#dcloud-appkey-是什么" aria-label="Permalink to &quot;DCloud AppKey 是什么？&quot;">​</a></h1><p>可以把它理解成：<strong>DCloud 给你这套「离线原生壳 + uni 资源包」发的授权码。</strong></p><blockquote><p><strong>注意：</strong> Android 和 iOS 的 AppKey 是分开的（同品牌、不同平台各有一串）。</p></blockquote><p>DCloud 的 uni-app 离线打包，不是随便把 <code>www</code> 塞进 APK 就能跑。运行时 DCloud 原生 SDK（5+ Runtime）会校验：</p><blockquote><p>这个 APK 有没有资格跑 <strong>这个 appid</strong> 的 uni 应用？</p></blockquote><p>Android 侧准确说是 <strong>四者</strong> 必须在 DCloud 开发者后台绑定一致（下文会细讲为何不是本地用 appid+包名算出来的）：</p><table tabindex="0"><thead><tr><th>要素</th><th>你们项目里在哪</th><th>示例（华源 hyqh）</th></tr></thead><tbody><tr><td>appid</td><td><code>dcloud_control.xml</code></td><td><code>__UNI__3EAF30F</code></td></tr><tr><td>Android 包名</td><td><code>build.gradle</code> → <code>applicationId</code></td><td><code>com.future.hyqhjskh</code></td></tr><tr><td>签名证书 SHA1</td><td>APK 实际签名（后台登记时提交）</td><td>Release keystore 对应 SHA1</td></tr><tr><td>AppKey</td><td><code>AndroidManifest.xml</code> → <code>dcloud_appkey</code></td><td>品牌配置里的那一串</td></tr></tbody></table><p>在 <a href="https://dev.dcloud.net.cn" target="_blank" rel="noreferrer">dev.dcloud.net.cn</a> 后台，针对应用 <code>__UNI__3EAF30F</code>，Android 平台会登记「包名 + 证书 SHA1 → AppKey」。<strong>任一项对不上</strong>，App 常见表现是：白屏、闪退、或提示未授权 / 校验失败。</p><h2 id="既然后台已有-appid-包名-为什么还要-appkey" tabindex="-1">既然后台已有 appid + 包名，为什么还要 AppKey？ <a class="header-anchor" href="#既然后台已有-appid-包名-为什么还要-appkey" aria-label="Permalink to &quot;既然后台已有 appid + 包名，为什么还要 AppKey？&quot;">​</a></h2><p>直觉是：后台查一下 appid、包名对上就放行。但问题是 <strong>校验发生在用户手机上的 APK 里</strong>，不是每次启动都去 DCloud 后台问一遍。</p><h3 id="appid-和包名都是「公开的」" tabindex="-1">appid 和包名都是「公开的」 <a class="header-anchor" href="#appid-和包名都是「公开的」" aria-label="Permalink to &quot;appid 和包名都是「公开的」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信息</th><th>能否保密</th></tr></thead><tbody><tr><td>appid <code>__UNI__3EAF30F</code></td><td>否，在 <code>manifest.json</code>、<code>dcloud_control.xml</code> 里明文</td></tr><tr><td>Android 包名</td><td>否，APK 里、<code>AndroidManifest</code> 里、应用商店里都能看到</td></tr><tr><td>uni 的 <code>www</code> 资源</td><td>否，解包就能拿到</td></tr></tbody></table><p>如果只校验「appid + 包名」：</p><ul><li>别人可以拿你们的 <code>www</code>，塞进自己的原生壳</li><li>把 appid 设成 <code>__UNI__3EAF30F</code></li><li>包名也改成 <code>com.future.hyqhjskh</code>（或仿冒）</li><li>就能 <strong>未授权</strong> 跑你们的 uni 业务</li></ul><p>单靠两个公开字段，无法证明「这个 APK 是你在 DCloud 后台登记过的合法离线包」。</p><h2 id="appkey-的角色-嵌进-apk-的「授权凭证」" tabindex="-1">AppKey 的角色：嵌进 APK 的「授权凭证」 <a class="header-anchor" href="#appkey-的角色-嵌进-apk-的「授权凭证」" aria-label="Permalink to &quot;AppKey 的角色：嵌进 APK 的「授权凭证」&quot;">​</a></h2><p>流程可以理解为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你在 dev.dcloud.net.cn 登记：</span></span>
<span class="line"><span>  appid + 平台(Android) + 包名 + 证书 SHA1</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>DCloud 生成一串 AppKey（只有登记过的开发者能拿到）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>你把 AppKey 写进 AndroidManifest 的 dcloud_appkey</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>App 启动时，DCloud SDK 校验：</span></span>
<span class="line"><span>  appid + 包名 + 实际 SHA1 + AppKey 是否与后台登记记录一致</span></span></code></pre></div><p>AppKey 相当于 DCloud 发的 <strong>离线打包许可证</strong>：</p><ul><li>证明你走过官方登记流程</li><li>绑定到具体的 appid + 平台 + 包名 + 证书 SHA1 组合</li><li>SDK 可以在 <strong>本地</strong> 做校验，不必每次启动都联网问后台（弱网、无网也能启动）</li></ul><h2 id="appkey-是-appid-包名算出来的吗" tabindex="-1">AppKey 是 appid+包名算出来的吗？ <a class="header-anchor" href="#appkey-是-appid-包名算出来的吗" aria-label="Permalink to &quot;AppKey 是 appid+包名算出来的吗？&quot;">​</a></h2><p><strong>不是。</strong> 「内置规则校验」容易让人以为是本地算法 <code>hash(appid + 包名)</code>，更准确的说法是：</p><h3 id="appkey-是-dcloud-后台登记时生成-的一串凭证" tabindex="-1">AppKey 是 DCloud <strong>后台登记时生成</strong> 的一串凭证 <a class="header-anchor" href="#appkey-是-dcloud-后台登记时生成-的一串凭证" aria-label="Permalink to &quot;AppKey 是 DCloud **后台登记时生成** 的一串凭证&quot;">​</a></h3><p>在 <a href="https://dev.dcloud.net.cn" target="_blank" rel="noreferrer">dev.dcloud.net.cn</a> 申请离线 AppKey 时，你要提交的不只是 appid 和包名，Android 还要填：</p><ul><li><strong>签名证书的 SHA1</strong>（以及 SHA256）</li></ul><p>后台根据这套登记信息 <strong>生成</strong> AppKey（例如 <code>71bfd9a85f08b0a0c80f54988af511b2</code>），不是你在本地用公式算出来的。</p><p><a href="https://nativesupport.dcloud.net.cn/AppDocs/usesdk/appkey.html" target="_blank" rel="noreferrer">官方文档</a> 原话大意是：appid + 应用包名 + 签名 SHA1 必须与申请时填写的一致，否则就会报「未配置 appkey 或配置错误」。</p><h3 id="运行时-sdk-实际在验什么" tabindex="-1">运行时 SDK 实际在验什么 <a class="header-anchor" href="#运行时-sdk-实际在验什么" aria-label="Permalink to &quot;运行时 SDK 实际在验什么&quot;">​</a></h3><p>DCloud SDK 在 <strong>App 启动时</strong>（闭源，仓库里看不到源码）大致会核对：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① dcloud_control.xml 里的 appid</span></span>
<span class="line"><span>② APK 实际包名 (applicationId)</span></span>
<span class="line"><span>③ APK 实际签名证书的 SHA1</span></span>
<span class="line"><span>④ AndroidManifest 里写的 dcloud_appkey 值</span></span></code></pre></div><p>这四项必须和你在 DCloud 后台 <strong>申请 AppKey 时登记的那条记录</strong> 对得上。<br> AppKey 本身是「后台发给你的许可证编号」；SDK 用它去匹配那条登记记录，<strong>不是</strong> <code>f(appid, 包名)</code> 本地推导。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>登记阶段（后台）：</span></span>
<span class="line"><span>  你提交：appid + 包名 + 证书 SHA1</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>  DCloud 生成：AppKey（存后台）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>运行阶段（手机）：</span></span>
<span class="line"><span>  SDK 从 APK 读出：appid、包名、实际 SHA1、manifest 里的 AppKey</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>  与后台登记记录比对（本地逻辑 + 可能联网，具体算法在闭源 SDK 里）</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>  全对 → 加载 www；不对 → 白屏/报错</span></span></code></pre></div><h2 id="appkey-与-android-签名证书的关系" tabindex="-1">AppKey 与 Android 签名证书的关系 <a class="header-anchor" href="#appkey-与-android-签名证书的关系" aria-label="Permalink to &quot;AppKey 与 Android 签名证书的关系&quot;">​</a></h2><p>AppKey <strong>不是</strong> keystore 文件本身，也 <strong>不是</strong> keystore 密码，但 <strong>和签名 SHA1 绑在一起</strong>：</p><ul><li>后台登记的是「某个包名 + 某张证书的 SHA1」</li><li>打出来的 APK 必须用 <strong>同一张证书</strong> 签，SDK 读到的 SHA1 才对得上</li></ul><table tabindex="0"><thead><tr><th></th><th>AppKey</th><th>Release 签名证书</th></tr></thead><tbody><tr><td>谁发的</td><td>DCloud</td><td>Google / 你们自己</td></tr><tr><td>防什么</td><td>未授权跑 uni 离线包</td><td>APK 被篡改、冒名发布</td></tr><tr><td>与 Debug 的关系</td><td>Debug 也要填 AppKey；SHA1 须与后台登记一致</td><td>Debug 默认用 debug 证书，SHA1 与 Release 不同</td></tr></tbody></table><p>如果 Debug 用 Android 默认 debug 证书，而后台只登记了 Release 证书的 SHA1，就会出现：<strong>AppKey 填对了，仍然报配置错误</strong>。</p><h2 id="四者各自干什么" tabindex="-1">四者各自干什么 <a class="header-anchor" href="#四者各自干什么" aria-label="Permalink to &quot;四者各自干什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置 / 信息</th><th>作用</th></tr></thead><tbody><tr><td><code>dcloud_control.xml</code></td><td>告诉 SDK：要加载哪个 uni 应用（appid）</td></tr><tr><td><code>AndroidManifest</code> 包名</td><td>告诉系统：这个 App 的身份</td></tr><tr><td>APK 签名 SHA1</td><td>证明 APK 用的是后台登记时那张证书</td></tr><tr><td><code>dcloud_appkey</code></td><td>告诉 SDK：你有权跑上面那个 appid</td></tr></tbody></table><p>启动时大致逻辑：</p><ol><li>读 <code>dcloud_control.xml</code> → 得到 <code>__UNI__3EAF30F</code></li><li>读当前 APK 包名 → <code>com.future.hyqhjskh</code></li><li>读 APK 实际签名 SHA1</li><li>读 <code>meta-data</code> <code>dcloud_appkey</code> → 那串 key</li><li>SDK 校验四者是否 <strong>在 DCloud 登记过的合法组合</strong></li><li><strong>通过</strong> → 加载 <code>assets/apps/__UNI__3EAF30F/www/</code></li><li><strong>失败</strong> → 白屏 / 未授权</li></ol><h2 id="gradle「appkey-为空就构建失败」——具体怎么写的" tabindex="-1">Gradle「AppKey 为空就构建失败」——具体怎么写的？ <a class="header-anchor" href="#gradle「appkey-为空就构建失败」——具体怎么写的" aria-label="Permalink to &quot;Gradle「AppKey 为空就构建失败」——具体怎么写的？&quot;">​</a></h2><p><strong>两件事分开说：Gradle 里的检查是你们工程自己写的；AppKey 校验不是本地用 appid+包名算出来的。</strong></p><p>这是 <strong><code>futures-android/simpleDemo/build.gradle</code> 里你们自己加的保护逻辑</strong>，不是 DCloud SDK 提供的，也 <strong>只在打 Release 时生效</strong>。</p><h3 id="_1-先读-appkey" tabindex="-1">1. 先读 AppKey <a class="header-anchor" href="#_1-先读-appkey" aria-label="Permalink to &quot;1. 先读 AppKey&quot;">​</a></h3><div class="language-gradle vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gradle</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def dcloudAppKey = hyqhProp(&#39;DCLOUD_APPKEY&#39;, &#39;HYQH_DCLOUD_APPKEY&#39;)</span></span></code></pre></div><p><code>hyqhProp</code> 的优先级：</p><ol><li>环境变量 <code>HYQH_DCLOUD_APPKEY</code></li><li>否则读 <code>futures-android/secrets.properties</code> 里的 <code>DCLOUD_APPKEY</code></li><li>都没有 → 空字符串 <code>&quot;&quot;</code></li></ol><h3 id="_2-在任务图就绪时拦截-release-构建" tabindex="-1">2. 在任务图就绪时拦截 Release 构建 <a class="header-anchor" href="#_2-在任务图就绪时拦截-release-构建" aria-label="Permalink to &quot;2. 在任务图就绪时拦截 Release 构建&quot;">​</a></h3><div class="language-gradle vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gradle</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradle.taskGraph.whenReady { graph -&gt;</span></span>
<span class="line"><span>    if (graph.hasTask(&#39;:simpleDemo:assembleRelease&#39;)) {</span></span>
<span class="line"><span>        if (releaseStorePassword.isEmpty() || releaseKeyPassword.isEmpty()) {</span></span>
<span class="line"><span>            throw new GradleException(</span></span>
<span class="line"><span>                    &#39;Release signing: set futures-android/secrets.properties (see secrets.properties.example) &#39; +</span></span>
<span class="line"><span>                            &#39;or HYQH_RELEASE_STORE_PASSWORD / HYQH_RELEASE_KEY_PASSWORD env vars.&#39;)</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        if (dcloudAppKey.isEmpty()) {</span></span>
<span class="line"><span>            throw new GradleException(</span></span>
<span class="line"><span>                    &#39;DCLOUD_APPKEY is empty: set futures-android/secrets.properties or HYQH_DCLOUD_APPKEY.&#39;)</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>点</th><th>说明</th></tr></thead><tbody><tr><td><code>gradle.taskGraph.whenReady</code></td><td>Gradle 解析完本次要跑哪些 task 之后、真正执行之前</td></tr><tr><td><code>graph.hasTask(&#39;:simpleDemo:assembleRelease&#39;)</code></td><td><strong>只有</strong>本次构建包含 <code>assembleRelease</code> 才检查</td></tr><tr><td><code>dcloudAppKey.isEmpty()</code></td><td>空串就 <code>throw new GradleException(...)</code>，构建直接失败</td></tr><tr><td><code>assembleDebug</code></td><td><strong>不会</strong>进这个分支，所以 Debug 构建 Gradle 不拦</td></tr></tbody></table><p>这是 <strong>纯 Gradle 层面的提前报错</strong>，避免打出没有 AppKey 的 Release 包。同一段里 Release 也会检查 keystore 密码是否为空。</p><h3 id="debug-也尽量用-release-证书" tabindex="-1">Debug 也尽量用 Release 证书 <a class="header-anchor" href="#debug-也尽量用-release-证书" aria-label="Permalink to &quot;Debug 也尽量用 Release 证书&quot;">​</a></h3><p><code>secrets.properties</code> 里有 keystore 密码时，<strong>Debug 也用 Release keystore 签名</strong>，这样 Debug APK 的 SHA1 才和 DCloud 后台登记的一致，AppKey 校验才过：</p><div class="language-gradle vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gradle</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buildTypes {</span></span>
<span class="line"><span>    debug {</span></span>
<span class="line"><span>        debuggable true</span></span>
<span class="line"><span>        if (!releaseStorePassword.isEmpty() &amp;&amp; !releaseKeyPassword.isEmpty()) {</span></span>
<span class="line"><span>            signingConfig signingConfigs.config</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="为什么-android-ios-各有一串-appkey" tabindex="-1">为什么 Android / iOS 各有一串 AppKey？ <a class="header-anchor" href="#为什么-android-ios-各有一串-appkey" aria-label="Permalink to &quot;为什么 Android / iOS 各有一串 AppKey？&quot;">​</a></h2><p>同一 appid，在 DCloud 后台 <strong>按平台、按包名 / Bundle ID 分别登记</strong>，会生成 <strong>不同的 AppKey</strong>。</p><p>你们项目里华源就是：</p><ul><li>Android：<code>offlinePackage.android.dcloudAppKey</code></li><li>iOS：<code>offlinePackage.ios.dcloudAppKey</code></li></ul><p>两串不一样，因为平台、包名规则都不同，<strong>不能混用</strong>。</p><h2 id="对照总结" tabindex="-1">对照总结 <a class="header-anchor" href="#对照总结" aria-label="Permalink to &quot;对照总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>Gradle 空 AppKey 失败谁写的？</td><td>你们 <code>build.gradle</code> 的 <code>taskGraph.whenReady</code>，仅 <code>assembleRelease</code></td></tr><tr><td>AppKey 是本地算法算出来的吗？</td><td><strong>不是</strong>，DCloud 后台根据登记信息生成</td></tr><tr><td>SDK 到底验什么？</td><td>appid + 包名 + <strong>APK 签名 SHA1</strong> + manifest 里的 AppKey，与后台登记记录一致</td></tr><tr><td>为何不能只要 appid+包名？</td><td>两者公开；AppKey + 签名 SHA1 才能证明「这是登记过的离线包」</td></tr></tbody></table><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p><strong>appid + 包名是公开身份；AppKey 是 DCloud 发的私密授权码，且与登记时的签名 SHA1 绑定。</strong></p><p>后台登记的是「谁有资格拿这串 key」；APK 里带上 key，SDK 才能在本地确认「这是合法离线包」，而不是随便一个壳 + 抄来的 <code>www</code>。</p><hr><p><strong>延伸阅读：</strong></p><ul><li><a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程（系列总览）</a></li><li><a href="/blog/posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程">Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程</a> — SHA1 指纹、四层生产要素与完整打包容流程</li><li><a href="/blog/posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么">Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么</a> — keystore 两个密码、空密码风险、安装验签</li><li><a href="/blog/posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同">SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同</a> — 证书指纹 vs 内容 hash、三平台发证对比</li></ul><p>若 AppKey 填错，可继续查 logcat 关键词，或按 <strong>Debug 报 AppKey 错误时的排查顺序</strong>（证书 SHA1 是否与后台登记一致）逐项核对。</p>`,69)])])}const g=a(d,[["render",n]]);export{u as __pageData,g as default};
